-- ============================================================
-- 004 · Orden del diagnóstico en endodoncia
--
-- Endodoncia es la única plantilla cuyo cuerpo trae sus propias
-- viñetas de diagnóstico y plan. En el escaneo original las dos
-- frases de enlace van INTERCALADAS entre esas viñetas:
--
--     "...me ha diagnosticado:"
--        · Patología dentaria destructiva de las piezas ...
--     "Para dicho diagnóstico me ha propuesto y presupuestado..."
--        · Endodoncia de las piezas ...
--     "En relación con el diagnóstico, el facultativo me ha explicado..."
--
-- El bloque compartido diagnostico_plan las emite seguidas, lo que
-- dejaba el diagnóstico DESPUÉS de "comprendo, que:". Para esta
-- plantilla se deja de usar el bloque y las frases vuelven al cuerpo.
--
-- Esto no reintroduce la duplicación que corrigió el 003: endodoncia
-- ya no referencia el bloque, así que cada frase aparece una vez.
--
-- Las otras 17 siguen con el bloque compartido: sus cuerpos no traen
-- viñetas propias y el orden les sale correcto.
-- ============================================================

begin;

update consent_plantillas
   set composicion = '[{"ref": "preambulo"}, {"ref": "identificacion"}, {"ref": "representante"}, {"nodos": [{"tipo": "lista", "items": ["Patología dentaria destructiva de las piezas {{tratamiento.piezas}}.", "Otras situaciones que originen dolor o hipersensibilidad pulpar en las piezas {{tratamiento.piezas}}."]}, {"tipo": "parrafo", "texto": "Para dicho diagnóstico me ha propuesto y presupuestado el siguiente plan de tratamiento:"}, {"tipo": "lista", "items": ["Endodoncia de las piezas {{tratamiento.piezas}}."]}, {"tipo": "parrafo", "texto": "En relación con el diagnóstico, el facultativo me ha explicado, y comprendo, que:"}, {"tipo": "parrafo", "texto": "La finalidad del tratamiento de conductos es poder conservar funcionalmente un diente cuya pulpa está irreversiblemente dañada; de otro modo, debería ser extraído para eliminar el dolor y/o la infección del diente, del hueso y de los tejidos perirradiculares."}, {"tipo": "parrafo", "texto": "Los procedimientos propios de la endodoncia van dirigidos al tratamiento de las patologías del complejo dentino-pulpar (conocido vulgarmente como el nervio del diente) intentando conservar al máximo las estructuras dentarias y su función. Dentro de estos tratamientos se incluyen básicamente las pulpectomías (eliminación de todo el tejido pulpar posible, vital o no, seguida por una desinfección, instrumentación y relleno u obturación del sistema cavitario intradentario donde se encontraba dicha pulpa) y las pulpotomías (eliminación parcial superficial del tejido pulpar seguida de una cobertura de la herida a la entrada de la raíz con sustancias medicamentosas). Este tratamiento precisará ser completado en el futuro con toda probabilidad. Ambos tratamientos pueden ser realizados mediante distintos procedimientos (manuales y/o mecánicos) y diversos materiales y técnicas de sellado o relleno."}, {"tipo": "parrafo", "texto": "Cuando sea necesario realizar una endodoncia en un diente inmaduro cuyo ápice no está completamente cerrado será necesario realizar previamente lo que se denomina apicogénesis y apicoformación, tratamientos que consisten en la inducción del cierre del conducto radicular mediante diferentes materiales. Una vez que dicho cierre se haya producido habrá que proceder a realizar la endodoncia de la pieza."}, {"tipo": "parrafo", "texto": "La única alternativa terapéutica existente a la endodoncia suele ser la extracción dentaria."}, {"tipo": "titulo", "texto": "Limitaciones y riesgos", "nivel": 2}, {"tipo": "parrafo", "texto": "El/la paciente ha sido informado/a y conoce las limitaciones y los riesgos estadísticamente frecuentes que puede comportar este tratamiento:"}, {"tipo": "lista", "items": ["Riesgos propios de la inyección de anestesia local: posibles hipersensibilidades al anestésico difícilmente previsibles, anestesias prolongadas, daños locales por la punción, excepcionalmente dolores neuropáticos, etc.", "Riesgo de fractura de la corona del diente endodonciado por la debilitación producida en el mismo por la endodoncia. Este suceso podría conllevar la necesidad de tratamiento protésico o extracción dental.", "Riesgo de fracturas o fisuras radiculares del diente endodonciado, por múltiples motivos difícilmente previsibles, y que conllevarían en la mayoría de los casos la pérdida del diente.", "Riesgo de la existencia de anomalías anatómicas en los conductos radiculares, difícilmente detectables por procedimientos radiológicos, que impidan la correcta limpieza y sellado de dicho conducto (conductos laterales, deltas apicales, calcificaciones, curvaturas extremas, etc.).", "Riesgo de no encontrar algún conducto radicular para su limpieza y sellado, sobre todo en dientes polirradiculares o con conductos accesorios. En caso de producirse esta eventualidad será debidamente informado.", "Riesgo de fractura del material empleado (limas, léntulos, material rotatorio, etc.) dentro del conducto radicular, hecho que no tiene por qué empeorar el pronóstico de la endodoncia. En cualquier caso el paciente será informado de este suceso y sus posibles consecuencias en caso de que se produzca.", "Riesgo de paso a los tejidos periapicales (los que rodean la raíz del diente) de parte de los productos utilizados para la limpieza y desinfección de los conductos radiculares (habitualmente productos que contienen hipoclorito sódico), o de los utilizados para sellar dichos conductos. Este paso accidental de estas sustancias puede provocar molestias postoperatorias, en ocasiones, importantes.", "Riesgo de ingestión, o más difícilmente aspiración, del pequeño material utilizado si no es posible o es muy dificultosa la utilización del dique de goma.", "Riesgo de pequeños daños en los tejidos blandos adyacentes al diente debido al uso del instrumental (clamps del dique de goma, instrumentos de corte de gutapercha, etc.).", "Riesgo de aparición de sensibilidad, dolor e incluso inflamación tras un procedimiento endodóncico correcto. Para la posible aparición de este supuesto, siempre imprevisible, se le darán las oportunas instrucciones.", "En el caso de que previamente a la endodoncia existiese un granuloma o quiste periapical, existe el riesgo de que no desaparezca tras ella y se precise cirugía periapical (técnica quirúrgica para llegar a la infección desde la encía) para su completa eliminación.", "Riesgo de alteración del color del diente endodonciado por la pérdida de vitalidad, difícilmente evitable y prevenible, y que implicaría la necesidad de tratamientos estéticos o protésicos."]}, {"tipo": "titulo", "texto": "Expectativas infundadas frecuentes", "nivel": 2}, {"tipo": "lista", "items": ["En la endodoncia, como en cualquier tratamiento odontológico, no existe «garantía de por vida». En condiciones normales, el éxito es del orden del 95 % (algo menor en los dientes infectados, en los que tienen anormalidades anatómicas).", "Si la endodoncia no produce la curación deseada, puede estar indicada la repetición del tratamiento de conductos o complementarlo con un tratamiento quirúrgico (apicectomía). En estos casos, las expectativas de éxito descienden a dos tercios de los casos. De no lograrse tampoco la curación, la indicación odontológica es la extracción (exodoncia)."]}, {"tipo": "titulo", "texto": "Advertencias importantes", "nivel": 2}, {"tipo": "lista", "items": ["Las diversas modalidades de tratamiento endodóncico no incluyen la reconstrucción o restauración del diente, que deberá realizarse posteriormente, como tratamiento aparte; admite diversas alternativas (principalmente, obturación —o empaste—, o refuerzos intrarradiculares y corona protésica), que ofrecen diferente resistencia a las fuerzas masticatorias.", "La existencia de una endodoncia no previene que ese diente padezca caries, enfermedad periodontal, o cualquier otra afección dentaria, que son patología distinta y ajena al tratamiento de conductos."]}]}, {"ref": "riesgos_personalizados"}, {"nodos": [{"tipo": "parrafo", "texto": "El paciente también ha sido informado de que los dientes endodonciados, debido a su debilidad, las fuerzas que soportan y al paso del tiempo, podrán sufrir deterioros (fisuras, fracturas, etc.) que harán necesario su revisión periódica. Para detectar estas circunstancias es informado que debe someterse a revisiones periódicas, en ningún caso espaciadas más de un año, y siempre que tenga cualquier tipo de molestia o duda sobre el tratamiento."}]}, {"ref": "declaracion"}, {"ref": "revocacion"}, {"ref": "proteccion_datos"}, {"ref": "lugar_fecha"}, {"ref": "firmas_paciente"}]'::jsonb
 where codigo = 'ENDODONCIA' and version = 1;

commit;

-- Comprobación: debe devolver exactamente 1 fila con cada frase.
select nodo->>'texto' as frase
  from consent_plantillas p,
       lateral jsonb_array_elements(p.composicion) item,
       lateral jsonb_array_elements(coalesce(item->'nodos','[]'::jsonb)) nodo
 where p.codigo = 'ENDODONCIA'
   and (nodo->>'texto' ilike 'Para dicho diagn%'
     or nodo->>'texto' ilike 'En relaci%n con el diagn%');
